(() => {
  const fams = ["E-PLAN","E-TASK","E-CLAIM","E-CRIT","E-EVD","E-WRITE","E-REASON","E-GENDB"];
  const src = fs.readFileSync(path.join(root, 'src/domain/gate_error.ts'), 'utf8');
  const doc = fs.readFileSync(path.join(root, 'docs/GUIDE-GATE.md'), 'utf8');
  const cnt = (f) => (src.match(new RegExp("code: [\"']" + f + "-[0-9]{3}[\"']", 'g')) || []).length;
  for (const f of fams) {
    const row = doc.match(new RegExp('\\| `' + f + '` \\|[^|]*\\|\\s*([0-9]+)\\s*\\|'));
    if (!row) return false;
    if (Number(row[1]) !== cnt(f) || cnt(f) === 0) return false;
  }
  const total = (doc.match(/码数合计[^0-9]*([0-9]+)/) || [])[1];
  const all = (src.match(/code: ["']E-[A-Z]+-[0-9]{3}["']/g) || []).length;
  return Number(total) === all && all === fams.reduce((s, f) => s + cnt(f), 0);
})()

(() => {
  const src = fs.readFileSync(path.join(root, 'src/domain/gate_error.ts'), 'utf8');
  const re = /messageStartsWith:\s*("((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)')/g;
  const vals = [];
  let m;
  while ((m = re.exec(src))) {
    const body = m[2] !== undefined ? m[2] : m[3];
    vals.push(body.replace(/\\(.)/g, '$1').replace(/\s+/g, ' ').trim());
  }
  if (!vals.length) return false;
  if (vals.some((v) => v === '')) return false;
  return new Set(vals).size === vals.length;
})()

(() => {
  const src = fs.readFileSync(path.join(root, 'src/domain/gate_error.ts'), 'utf8');
  // ★ 豁免清单：这些码的原文开头是可变的 who / action / expectations[下标]，或压根不是一句拒绝，
  //   或与邻码同一句 ⇒ 结构性接不上 messageStartsWith。**逐条写死**，等价于旧版那句「剩下 21 条」的口径。
  const EXEMPT = {"E-PLAN-003":1, "E-PLAN-004":1, "E-PLAN-005":1, "E-PLAN-006":1, "E-PLAN-011":1, "E-PLAN-012":1, "E-PLAN-013":1, "E-PLAN-014":1, "E-PLAN-015":1, "E-PLAN-016":1, "E-PLAN-017":1, "E-PLAN-019":1, "E-PLAN-020":1, "E-TASK-006":1, "E-CLAIM-008":1, "E-CLAIM-012":1, "E-CLAIM-013":1, "E-CRIT-002":1, "E-WRITE-002":1, "E-WRITE-003":1, "E-REASON-006":1};
  const codeRe = /code:\s*["'](E-[A-Z]+-\d{3})["']/g;
  const marks = [];
  let m;
  while ((m = codeRe.exec(src))) marks.push({ code: m[1], at: m.index });
  if (!marks.length) return false;
  const withPrefix = new Set();
  for (let i = 0; i < marks.length; i++) {
    const end = i + 1 < marks.length ? marks[i + 1].at : src.length;
    if (/messageStartsWith:/.test(src.slice(marks[i].at, end))) withPrefix.add(marks[i].code);
  }
  // ① 每一条码：要么有前缀（能反查），要么在豁免清单里 —— 一条都不许没交代
  for (const c of marks.map((x) => x.code)) if (!withPrefix.has(c) && !(c in EXEMPT)) return false;
  // ② 反向：豁免清单里的码必须真的没有前缀 —— 补上了就得从清单删，否则豁免会烂掉
  for (const c of Object.keys(EXEMPT)) if (withPrefix.has(c)) return false;
  return true;
})()

