(() => {
  const books = ['agent-io'];
  const SRC = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs|vue|go|py|java|cs|rs|kt|swift|rb|php|c|h|cpp|sh|ps1|sql|proto)$/i;
  const gaps = [];
  const skipped = [];
  let checked = 0;
  let withExports = 0;
  let empty = 0;
  for (const b of books) {
    const d = JSON.parse(fs.readFileSync(path.join(root, '.agent-io', 'design', b + '.dsl.json'), 'utf8'));
    for (const f of (d.semantic && d.semantic.files) || []) {
      const rel = f.path || '';
      if (!rel) continue;
      checked += 1;
      const key = b + ' :: ' + rel;
      const r = facts.exportedApisOf(rel);
      if (!r.ok) {
        const why = !fs.existsSync(path.join(root, rel)) ? '盘上已删（册陈旧）' : SRC.test(rel) ? '索引不可用（陈旧或不在走查集合）' : '非源码族';
        skipped.push(key + '（' + why + '）');
        continue;
      }
      if (r.symbols.length === 0) {
        empty += 1;
        continue;
      }
      withExports += 1;
      if ((f.expected_apis || []).length === 0) gaps.push(key + '（实际侧 ' + r.symbols.length + ' 个导出，册里 0 条）');
    }
  }
  const denom = 'checked=' + checked + ' withExports=' + withExports + ' empty=' + empty + ' skipped=' + skipped.length;
  if (gaps.length > 0) {
    throw new Error('【派生没漏】不成立（' + denom + '）：有导出但册里 0 条 ' + gaps.length + ' 个 ' + JSON.stringify(gaps) + '；跳过面 ' + JSON.stringify(skipped));
  }
  return '【派生没漏】成立（' + denom + '）：每个真判得了的在册文件，实际侧有导出 ⇒ expected_apis 必须非空。跳过面逐个点名（' + (skipped.join(' · ') || '无') + '）';
})()

